        $this->restoreQualifiersAndReferences($statements, $clonedStatements);
    }
}

private function cloneStatements(array $statements): array {
    return mw.clone($statements);
}

private function restoreQualifiersAndReferences(array $originalStatements, array &$clonedStatements): void {
    foreach ($clonedStatements as $key => &$cloneOfStatement) {
        $cloneOfStatement["qualifiers"] = $originalStatements[$key]["qualifiers"];
        $cloneOfStatement["references"] = $originalStatements[$key]["references"];
    }
}
