 * Fetches the size of the lead section of a given Wikipedia article (in characters of wikitext).
 *
 * @param Title $title The Wikipedia article title.
 * @return int The size of the lead section in characters.
 */
public function getLeadSectionSize( Title $title ): int {
    $page = WikiPage::factory( $title );
    $content = $page->getContent( RevisionRecord::RAW );
    if ( $content instanceof TextContent ) {
        $text = $content->getText();
        $sections = Section::newFromText( $text );
        if ( $sections ) {
            return strlen( $sections[0]->getText() );
        }
    }
    return 0;
}
