const timeout = 30000; // Use the default 30 seconds timeout
let currentRequest = null;

const executeLint = async (doc) => {
	if (currentRequest) {
		currentRequest.abort();
	}

	currentRequest = new AbortController();
	try {
		const errors = await rest.post('/v1/transform/wikitext/to/lint', {
			wikitext: doc.toString()
		}, {
			signal: currentRequest.signal
		});
		return errors;
	} catch (error) {
		if (error.name === 'AbortError') {
			mw.log.warn('[CodeMirror] Lint request aborted');
		} else {
			mw.log.warn('[CodeMirror] Error during lint request:', error);
		}
		return null;
	} finally {
		currentRequest = null;
	}
};
